package driver

import (
	"context"
	"fmt"
	"net/http"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"

	"github.com/IBM/sarama"
	"github.com/signadot/hotrod/pkg/kafka"
	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/tracing"
	"go.uber.org/zap"
)

type Processor struct {
	logger log.Factory
}

func NewProcessor(logger log.Factory) *Processor {
	return &Processor{
		logger: logger,
	}
}

// Run starts the Driver server
func (p *Processor) Run() error {
	ctx, cancel := context.WithCancel(context.Background())

	p.logger.For(ctx).Info("Starting a new consumer")

	// get a tracer provider for the driver
	tracerProvider := tracing.InitOTEL("driver", p.logger)

	// create a consumer handler
	consumer := newConsumer(ctx, tracerProvider, p.logger)

	// create a new tracer provider for kafka
	kafkaTracerProvider := tracing.InitOTEL("kafka", p.logger)

	var (
		consumerGroup sarama.ConsumerGroup
		handler       sarama.ConsumerGroupHandler
		err           error
	)
	ticker := time.NewTicker(time.Second / 2)
	defer ticker.Stop()
	for {
		// create a consumer group
		consumerGroup, handler, err = kafka.GetConsumerGroup(
			"hotrod-driver", "driver", kafkaTracerProvider, consumer)
		if err == nil {
			break
		}
		select {
		case <-ctx.Done():
			cancel()
			return fmt.Errorf("error creating consumer group client: %v", err)
		case <-ticker.C:
			p.logger.For(ctx).Error("error creating consumer group client", zap.Error(err))
			p.logger.For(ctx).Info("retrying")
		}
	}

	wg := &sync.WaitGroup{}
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			// `Consume` should be called inside an infinite loop, when a
			// server-side rebalance happens, the consumer session will need to be
			// recreated to get the new claims
			err := consumerGroup.Consume(ctx, []string{kafka.DispatchDriverTopic}, handler)
			if err != nil {
				p.logger.For(ctx).Error("Error from consumer", zap.Error(err))
			}
			// check if context was cancelled, signaling that the consumer should stop
			if ctx.Err() != nil {
				return
			}
			consumer.ready = make(chan bool)
		}
	}()

	<-consumer.ready // Await till the consumer has been set up
	p.logger.For(ctx).Info("Consumer up and running!")
	http.Handle("/healthz", http.HandlerFunc(func(resp http.ResponseWriter, req *http.Request) {
		p.logger.For(ctx).Info("handling /healthz")
		resp.Write([]byte("ok"))
	}))
	go http.ListenAndServe(":8082", http.DefaultServeMux)

	sigterm := make(chan os.Signal, 1)
	signal.Notify(sigterm, syscall.SIGINT, syscall.SIGTERM)

	keepRunning := true
	for keepRunning {
		select {
		case <-ctx.Done():
			p.logger.For(ctx).Info("terminating: context cancelled")
			keepRunning = false
		case <-sigterm:
			p.logger.For(ctx).Info("terminating: via signal")
			keepRunning = false
		}
	}
	cancel()
	wg.Wait()
	if err := consumerGroup.Close(); err != nil {
		p.logger.For(ctx).Error("could not close kafka consumer group", zap.Error(err))
	}
	return nil
}
package driver

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/dnwe/otelsarama"
	"github.com/signadot/hotrod/pkg/baggageutils"
	"github.com/signadot/hotrod/pkg/config"
	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/notifications"
	"github.com/signadot/routesapi/go-routesapi"
	"github.com/signadot/routesapi/go-routesapi/watched"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/IBM/sarama"
)

// Consumer represents a Sarama consumer group consumer
type Consumer struct {
	tracer       trace.Tracer
	logger       log.Factory
	routing      watched.BaselineWatched
	driverStore  *driverStore
	bestETA      *bestETA
	notification notifications.Interface
	ready        chan bool
}

func newConsumer(ctx context.Context, tracerProvider trace.TracerProvider,
	logger log.Factory) *Consumer {
	// create a routesapi baseline watched instance
	// TODO: remove this in case we're not running with Signadot
	//
	// Virtual workloads are excluded: shouldProcess treats "no routing rule"
	// as "the baseline handles it", which is exactly what a virtual workload
	// means.
	routing, err := watched.BaselineWatchedFromEnv(&routesapi.ClientInfo{
		EnableVirtualWorkloads: false,
	})
	if err != nil {
		panic(err)
	}

	tracer := tracerProvider.Tracer("driver")
	return &Consumer{
		tracer:       tracer,
		logger:       logger,
		routing:      routing,
		driverStore:  newDriverStore(tracer, logger),
		bestETA:      newBestETA(tracerProvider, tracer, logger),
		notification: notifications.NewNotificationHandler(tracerProvider, logger),
		ready:        make(chan bool),
	}
}

// Setup is run at the beginning of a new session, before ConsumeClaim
func (consumer *Consumer) Setup(sarama.ConsumerGroupSession) error {
	// Mark the consumer as ready
	close(consumer.ready)
	return nil
}

// Cleanup is run at the end of a session, once all ConsumeClaim goroutines have exited
func (consumer *Consumer) Cleanup(sarama.ConsumerGroupSession) error {
	return nil
}

// ConsumeClaim must start a consumer loop of ConsumerGroupClaim's Messages().
func (consumer *Consumer) ConsumeClaim(session sarama.ConsumerGroupSession, claim sarama.ConsumerGroupClaim) error {
	for {
		select {
		case message, ok := <-claim.Messages():
			if !ok {
				consumer.logger.Bg().Error("message channel was closed")
				return nil
			}
			session.MarkMessage(message, "")
			consumer.processDispatchRequest(message)
		case <-session.Context().Done():
			return nil
		}
	}
}

func (consumer *Consumer) shouldProcess(routingKey string) bool {
	if sbName := config.SignadotSandboxName(); sbName != "" {
		return consumer.routing.RoutesTo(routingKey, sbName)
	}
	return consumer.routing.Get(routingKey) == nil
}

func (consumer *Consumer) processDispatchRequest(msg *sarama.ConsumerMessage) {
	// Extract tracing info from message
	ctx := otel.GetTextMapPropagator().Extract(context.Background(), otelsarama.NewConsumerMessageCarrier(msg))

	// should we process this message?
	routingKey := baggageutils.GetRoutingKey(ctx)

	if !consumer.shouldProcess(routingKey) {
		// this message is not intended for us
		return
	}

	// extract the request context
	reqContext, err := baggageutils.ExtractRequestContext(ctx)
	if err != nil {
		consumer.logger.For(ctx).Error("cannot extract request context from baggage", zap.Error(err))
		return
	}
	if reqContext == nil {
		consumer.logger.For(ctx).Error("empty request context from baggage, ignoring request")
		return
	}

	ctx, span := consumer.tracer.Start(ctx, "ProcessDispatchRequest", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		semconv.MessagingOperationProcess,
		attribute.
			Key("session.id").
			Int(int(reqContext.SessionID)),
	)
	defer span.End()

	// parse the message body
	var dispatchReq DispatchRequest
	err = json.Unmarshal(msg.Value, &dispatchReq)
	if err != nil {
		consumer.logger.For(ctx).Error("error decoding message body")
		span.SetStatus(codes.Error, err.Error())
		return
	}

	// send a notification
	notificationCtx := consumer.notification.NotificationContext(
		reqContext, baggageutils.GetRoutingKey(ctx))
	consumer.notification.Store(ctx, &notifications.Notification{
		ID:        fmt.Sprintf("req-%d-finding-driver", reqContext.ID),
		Timestamp: time.Now(),
		Context:   notificationCtx,
		Body:      "Finding an available driver",
	})

	// find availanble drivers
	driverIDs := consumer.driverStore.FindDriverIDs(ctx)

	// populate current driver's locations
	drivers, err := consumer.driverStore.GetDriversLocation(ctx, driverIDs)
	if err != nil {
		span.SetStatus(codes.Error, err.Error())
		return
	}

	// get the driver with the best ETA
	bestDriver, err := consumer.bestETA.Get(ctx, &dispatchReq, drivers)
	if err != nil {
		consumer.logger.For(ctx).Error("error calculating best route", zap.Error(err))
		span.SetStatus(codes.Error, err.Error())
		return
	}

	// send a notification
	consumer.notification.Store(ctx, &notifications.Notification{
		ID:        fmt.Sprintf("req-%d-dispatched-driver", reqContext.ID),
		Timestamp: time.Now(),
		Context:   notificationCtx,
		Body:      fmt.Sprintf("Driver %s arriving in %s", bestDriver.DriverID, bestDriver.ETA.String()),
	})
}
package driver

import (
	"github.com/signadot/hotrod/services/location"
)

type DispatchRequest struct {
	PickupLocation  *location.Location `json:"pickupLocation"`
	DropoffLocation *location.Location `json:"dropoffLocation"`
}

type Driver struct {
	DriverID    string
	Coordinates string
}

