// ListRideHistory implements location.Interface#ListRideHistory as an RPC
func (c *Client) ListRideHistory(ctx context.Context) (*RideHistoryList, error) {
	c.logger.For(ctx).Info("Getting ride history")

	url := fmt.Sprintf("http://%s/ride-history", c.hostPort)
