// CreateRideHistory implements location.Interface#CreateRideHistory as an RPC
func (c *Client) CreateRideHistory(ctx context.Context, entry *RideHistoryEntry) (*RideHistoryEntry, error) {
	c.logger.For(ctx).Info("Creating ride history entry")

	url := fmt.Sprintf("http://%s/ride-history", c.hostPort)
	var created RideHistoryEntry
	if err := c.sendJSON(ctx, http.MethodPost, url, entry, &created); err != nil {
		return nil, err
	}
	return &created, nil
}

// UpdateRideHistory implements location.Interface#UpdateRideHistory as an RPC
func (c *Client) UpdateRideHistory(ctx context.Context, update *RideHistoryUpdate) (*RideHistoryEntry, error) {
	c.logger.For(ctx).Info("Updating ride history entry", zap.Int64("id", update.ID))

	url := fmt.Sprintf("http://%s/ride-history", c.hostPort)
	var updated RideHistoryEntry
	if err := c.sendJSON(ctx, http.MethodPatch, url, update, &updated); err != nil {
		return nil, err
	}
	return &updated, nil
}

// sendJSON sends reqIn as JSON using method and decodes the JSON response into respOut.
func (c *Client) sendJSON(ctx context.Context, method, url string, reqIn, respOut interface{}) error {
	d, err := json.Marshal(reqIn)
	if err != nil {
		return err
	}
	req, err := http.NewRequestWithContext(ctx, method, url, bytes.NewBuffer(d))
	if err != nil {
		return err
	}
	req.Header.Add("Content-type", "application/json")

	res, err := c.client.Client.Do(req)
	if err != nil {
		return err
	}
	defer res.Body.Close()

	if res.StatusCode >= 400 {
		body, err := io.ReadAll(res.Body)
		if err != nil {
			return err
		}
		return errors.New(string(body))
	}
	return json.NewDecoder(res.Body).Decode(respOut)
}
