import {LogEntry} from "../hooks/useLogs.tsx";

export type DriverNotification = {
    plate?: string,
    fare?: number,
}

/**
 * Extracts the driver plate and fare from the driver notification, which looks like
 * "Driver <plate> arriving in <eta>. Fare: $<amount>".
 */
export const parseDriverNotification = (entries: LogEntry[]): DriverNotification => {
    const result: DriverNotification = {};
    for (const entry of entries) {
        if (entry.service !== 'driver') continue;

        const plate = entry.status.match(/Driver\s+(.*?)\s+arriving/);
        if (plate && result.plate === undefined) {
            result.plate = plate[1];
        }

        const fare = entry.status.match(/Fare:\s*\$(\d+(?:\.\d+)?)/);
        if (fare && result.fare === undefined) {
            result.fare = parseFloat(fare[1]);
        }
    }
    return result;
};

export const formatFare = (fare: number) => `$${fare.toFixed(2)}`;
