export const apiPatch = async <R>(path: string, data: Record<string, string> | object) => {
    const d = await fetch(path, {
        headers: {
            "Content-Type": "application/json",
        },
        method: "PATCH",
        body: JSON.stringify(data),
    })
    if (!d.ok) {
        throw new Error(await d.text())
    }
    const json = await d.json()
    return json as R
}
