input.code:
async (page) => {
  await page.unrouteAll();
  const key = 'wwt7ghfxg5uh2';
  await page.route('http://ride-history-val-frontend-0ff1e7d0.ctbench-hotrod.svc:8080/**', async route => {
    const h = route.request().headers();
    const bag = h['baggage'] ? h['baggage'] + ', sd-routing-key=' + key : 'sd-routing-key=' + key;
    await route.continue({ headers: { ...h, baggage: bag, tracestate: 'sd-routing-key=' + key } });
  });
  await page.goto('http://ride-history-val-frontend-0ff1e7d0.ctbench-hotrod.svc:8080/');
  await page.waitForLoadState('networkidle');
  const selects = page.locator('select');
  await selects.nth(0).selectOption({ label: "Rachel's Floral Designs" });
  await selects.nth(1).selectOption({ label: 'Trom Chocolatier' });
  await page.getByRole('button', { name: 'Request Ride' }).click();
  await page.waitForTimeout(25000);
  return (await page.innerText('body')).slice(0, 900);
}

